17	        if (amount != null && amount.signum() > 0 && paid.compareTo(amount) >= 0) {
18	            return "PAID";
19	        }
20	        if (paid.signum() > 0) {
21	            return "PARTIAL";
22	        }
23	        return storedStatus;
24	    }
