1	import React, { useEffect, useState } from 'react';
2	import { InvoiceLineItems } from './InvoiceLineItems';
3	import { InvoicePayments } from './InvoicePayments';
4	
5	// A project's invoices, rendered inside the projects feature when a project is opened. Lists the
6	// project's invoices, shows their derived total (amounts to 2 decimals), and adds a new invoice by
7	// amount. Each invoice's status is worked out from the payments recorded against it — PARTIAL once
8	// some is paid, PAID once covered — rather than being flipped to paid by hand. Opening an invoice
9	// (invoice-open-<id>) shows its derived status, its line items — the things being charged for — and
10	// its payments in place of the list. Owns its own state and data loading (no global store);
11	// composed, not branched.
12	type Invoice = {
13	  id: number;
14	  projectId: number;
15	  amount: number;
16	  due: number;
17	  status: string;
18	  issuedDate: string | null;
19	  dueDate: string | null;
20	};
21	
22	function formatAmount(amount: number): string {
23	  return `$${Number(amount).toLocaleString('en-US', {
24	    minimumFractionDigits: 2,
25	    maximumFractionDigits: 2,
26	  })}`;
27	}
28	
29	export function ProjectInvoices({ projectId }: { projectId: number }) {
30	  const [invoices, setInvoices] = useState<Invoice[]>([]);
31	  const [amount, setAmount] = useState('');
32	  const [error, setError] = useState('');
33	  const [sort, setSort] = useState<'id' | 'due'>('id');
34	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
35	  const [openStatus, setOpenStatus] = useState('');
36	
37	  async function load(order: 'id' | 'due' = sort) {
38	    const res = await fetch(`/api/projects/${projectId}/invoices?sort=${order}`);
39	    setInvoices(await res.json());
40	  }
41	
42	  // The opened invoice's status is derived from its payments, so re-read it on open and whenever a
43	  // payment is recorded against it.
44	  async function loadInvoice(invoiceId: number) {
45	    const res = await fetch(`/api/invoices/${invoiceId}`);
46	    if (!res.ok) {
47	      return;
48	    }
49	    const inv: Invoice = await res.json();
50	    setOpenStatus(inv.status);
51	  }
52	
53	  useEffect(() => {
54	    void load();
55	  }, [projectId]);
56	
57	  useEffect(() => {
58	    if (openInvoiceId !== null) {
59	      void loadInvoice(openInvoiceId);
60	    }
61	  }, [openInvoiceId]);
62	
63	  async function sortByDue() {
64	    setSort('due');
65	    await load('due');
66	  }
67	
68	  async function onSubmit(e: React.FormEvent) {
69	    e.preventDefault();
70	    const value = Number(amount);
71	    if (!(value > 0)) {
72	      setError('Amount must be greater than zero');
73	      return;
74	    }
75	    setError('');
76	    const res = await fetch(`/api/projects/${projectId}/invoices`, {
77	      method: 'POST',
78	      headers: { 'Content-Type': 'application/json' },
79	      body: JSON.stringify({ amount: Number(amount) }),
80	    });
81	    if (!res.ok) {
82	      return;
83	    }
84	    setAmount('');
85	    await load();
86	  }
87	
88	  async function send(invoiceId: number) {
89	    const res = await fetch(`/api/invoices/${invoiceId}/send`, { method: 'POST' });
90	    if (!res.ok) {
91	      return;
92	    }
93	    await load();
94	  }
95	
96	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
97	
98	  if (openInvoiceId !== null) {
99	    return (
100	      <section data-testid="project-invoices">
101	        <h2>Invoices</h2>
102	        <p>
103	          Status: <span data-testid="invoice-status">{openStatus}</span>
104	        </p>
105	        <InvoiceLineItems
106	          invoiceId={openInvoiceId}
107	          onClose={() => {
108	            setOpenInvoiceId(null);
109	            void load();
110	          }}
111	        />
112	        <InvoicePayments
113	          invoiceId={openInvoiceId}
114	          onRecorded={() => void loadInvoice(openInvoiceId)}
115	        />
116	      </section>
117	    );
118	  }
119	
120	  return (
121	    <section data-testid="project-invoices">
122	      <h2>Invoices</h2>
123	
124	      <form data-testid="invoice-form" onSubmit={onSubmit}>
125	        <input
126	          data-testid="invoice-form-amount"
127	          placeholder="Amount"
128	          value={amount}
129	          onChange={(e) => setAmount(e.target.value)}
130	        />
131	        <button type="submit" data-testid="invoice-form-submit">
132	          Add invoice
133	        </button>
134	        {error ? (
135	          <p data-testid="invoice-form-amount-error" role="alert">
136	            {error}
137	          </p>
138	        ) : null}
139	      </form>
140	
141	      <button type="button" data-testid="invoice-sort-due" onClick={() => void sortByDue()}>
142	        Sort by due date
143	      </button>
144	
145	      <table data-testid="project-invoices-table">
146	        <thead>
147	          <tr>
148	            <th>Amount</th>
149	            <th>Due</th>
150	            <th>Status</th>
151	            <th>Issued</th>
152	            <th>Due</th>
153	            <th></th>
154	          </tr>
155	        </thead>
156	        <tbody>
157	          {invoices.map((inv) => (
158	            <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
159	              <td data-testid="invoice-amount">{formatAmount(inv.amount)}</td>
160	              <td data-testid="invoice-due-amount">{formatAmount(inv.due)}</td>
161	              <td data-testid="invoice-status">{inv.status}</td>
162	              <td data-testid="invoice-issued">{inv.issuedDate ?? ''}</td>
163	              <td data-testid="invoice-due">{inv.dueDate ?? ''}</td>
164	              <td>
165	                <button
166	                  type="button"
167	                  data-testid={`invoice-open-${inv.id}`}
168	                  onClick={() => setOpenInvoiceId(inv.id)}
169	                >
170	                  Open
171	                </button>
172	                {inv.status === 'DRAFT' ? (
173	                  <button
174	                    type="button"
175	                    data-testid={`invoice-send-${inv.id}`}
176	                    onClick={() => void send(inv.id)}
177	                  >
178	                    Send
179	                  </button>
180	                ) : null}
181	              </td>
182	            </tr>
183	          ))}
184	        </tbody>
